# Shell problem — reference simulation of the grep behavior
import re

class Solution:
    def validPhoneNumbers(self, text: str) -> list[str]:
        pat = re.compile(r'^(\d{3}-\d{3}-\d{4}|\(\d{3}\) \d{3}-\d{4})$')
        return [line for line in text.splitlines() if pat.match(line)]

