// Shell problem — reference C++ equivalent using std::regex
class Solution {
public:
    vector<string> validPhoneNumbers(const string& text) {
        regex pat("^(\\d{3}-\\d{3}-\\d{4}|\\(\\d{3}\\) \\d{3}-\\d{4})$");
        vector<string> res;
        stringstream ss(text);
        string line;
        while (getline(ss, line))
            if (regex_match(line, pat)) res.push_back(line);
        return res;
    }
};

