// Shell problem — reference Java equivalent
import java.util.*;
import java.util.regex.*;

class Solution {
    public List<String> validPhoneNumbers(String text) {
        Pattern p = Pattern.compile("^(\\d{3}-\\d{3}-\\d{4}|\\(\\d{3}\\) \\d{3}-\\d{4})$");
        List<String> res = new ArrayList<>();
        for (String line : text.split("\n"))
            if (p.matcher(line).matches()) res.add(line);
        return res;
    }
}

